    justify-content: space-between;
    align-items: center;
    position: sticky;
    top: 0;
    z-index: 50;
    box-shadow: 0 4px 6px rgba(0,0,0,0.3);
}

.logo {
    font-size: 1.5rem;
    font-weight: bold;
    color: var(--primary-color);
    text-decoration: none;
    letter-spacing: 1px;
}

nav ul {
    list-style: none;
    display: flex;
    gap: var(--spacing-lg);
    margin: 0;
    padding: 0;
}

nav a {
    color: var(--text-primary);
    text-decoration: none;
    font-weight: 500;
    transition: color var(--transition-speed);
}

nav a:hover, nav a:focus {
    color: var(--primary-color);
    outline: none;
}

nav a:focus-visible {
    outline: var(--focus-outline);
    outline-offset: 4px;
}

main {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--spacing-lg);
}

main:focus {
    outline: none;
}

section {
    margin-bottom: var(--spacing-xl);
}

h1, h2, h3 {
    margin-top: 0;
    color: var(--on-surface);
}

.hero {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: flex-start;
    min-height: 60vh;
    background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), url('https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1200&q=80');
    background-size: cover;
    background-position: center;
    padding: var(--spacing-xl);
    border-radius: var(--border-radius);
    margin-top: var(--spacing-md);
}

.hero h1 {
    font-size: 3.5rem;
    margin-bottom: var(--spacing-md);
    line-height: 1.1;
}

.hero p {
    font-size: 1.25rem;
    max-width: 600px;
    margin-bottom: var(--spacing-lg);
    color: var(--text-primary);
}

.btn {
    display: inline-block;
    padding: 12px 24px;
    border-radius: var(--border-radius);
    text-decoration: none;
    font-weight: bold;
    transition: transform 0.2s, background-color 0.2s;
    border: none;
    cursor: pointer;
}

.btn-primary {
    background-color: var(--primary-color);
    color: var(--on-primary);
}

.btn-primary:hover, .btn-primary:focus {
    background-color: #d7b4ff;
    transform: translateY(-2px);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: var(--spacing-lg);
}

.product-card {
    background-color: var(--surface-color);
    border-radius: var(--border-radius);
    overflow: hidden;
    transition: transform 0.3s, box-shadow 0.3s;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 10px 20px rgba(0,0,0,0.4);
}

.product-image {
    width: 100%;
    aspect-ratio: 1;
    background-color: var(--surface-alt);
    object-fit: cover;
}

.product-info {
    padding: var(--spacing-md);
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.product-title {
    font-size: 1.2rem;
    margin-bottom: var(--spacing-xs);
    color: var(--on-surface);
    text-decoration: none;
}

.product-title:hover {
    text-decoration: underline;
}

.product-price {
    font-weight: bold;
    color: var(--secondary-color);
    margin-bottom: var(--spacing-md);
}

.add-to-cart {
    margin-top: auto;
    width: 100%;
    background-color: transparent;
    border: 1px solid var(--primary-color);
    color: var(--primary-color);
    padding: 8px;
    border-radius: var(--border-radius);
    cursor: pointer;
    transition: background-color 0.2s, color 0.2s;
}

.add-to-cart:hover, .add-to-cart:focus {
    background-color: var(--primary-color);
    color: var(--on-primary);
}

.deals-section {
    background-color: var(--surface-alt);
    padding: var(--spacing-lg);
    border-radius: var(--border-radius);
}

.deal-badge {
    background-color: var(--error-color);
    color: white;
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 0.8rem;
    font-weight: bold;
    text-transform: uppercase;
    display: inline-block;
    margin-bottom: var(--spacing-sm);
}

footer {
    background-color: var(--surface-color);
    padding: var(--spacing-xl) var(--spacing-lg);
    margin-top: var(--spacing-xl);
    border-top: 1px solid var(--surface-alt);
}

.footer-content {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-xl);
}

.footer-section h2 {
    font-size: 1.2rem;
    margin-bottom: var(--spacing-md);
}

.footer-links {
    list-style: none;
    padding: 0;
    margin: 0;
}

.footer-links li {
    margin-bottom: var(--spacing-sm);
}

.footer-links a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: color 0.2s;
}

.footer-links a:hover {
    color: var(--primary-color);
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

@media (max-width: 768px) {
    .hero h1 {
        font-size: 2.5rem;
    }
    header {
        flex-direction: column;
        gap: var(--spacing-md);
    }
}
