    const css = fs.readFileSync('style.css', 'utf8');
    const js = fs.readFileSync('script.js', 'utf8');

    // Create a JSDOM instance
    const dom = new JSDOM(html, {
        runScripts: "dangerously",
        resources: "usable"
    });

    // Inject CSS
    const style = dom.window.document.createElement('style');
    style.textContent = css;
    dom.window.document.head.appendChild(style);

    // Inject JS and wait for it to run (App() call)
    const script = dom.window.document.createElement('script');
    script.textContent = js;
    dom.window.document.body.appendChild(script);

    // Give it a moment to render
    await new Promise(resolve => setTimeout(resolve, 500));

    // Run axe on the JSDOM document
    const results = await axe.run(dom.window.document.body);

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(JSON.stringify({
        wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, targets: v.nodes.map(n => n.target) })),
        bp: bp.map(v => ({ id: v.id, help: v.help, targets: v.nodes.map(n => n.target) }))
    }, null, 2));

    process.exit(wcag.length > 0 ? 1 : 0);
}

runAudit().catch(err => {
    console.error(err);
    process.exit(1);
});
